// ═══ DEADLOCK CODE — classic example ═══
Object lockA = new Object();
Object lockB = new Object();

// Thread-1: locks A then B
Thread t1 = new Thread(() -> {
    synchronized (lockA) {          // holds A
        sleep(50);                   // gives t2 time to lock B
        synchronized (lockB) {      // waits for B — held by t2!
            System.out.println("T1 done");
        }
    }
});

// Thread-2: locks B then A (OPPOSITE order!)
Thread t2 = new Thread(() -> {
    synchronized (lockB) {          // holds B
        sleep(50);                   // gives t1 time to lock A
        synchronized (lockA) {      // waits for A — held by t1!
            System.out.println("T2 done");
        }
    }
});

t1.start(); t2.start();
// DEADLOCK! T1 holds A, waits for B. T2 holds B, waits for A. FOREVER.

// ═══ FIX: consistent lock ordering ═══
// ALWAYS lock A before B (e.g., by object identity hash or ID)
Thread t1Fixed = new Thread(() -> {
    synchronized (lockA) {          // A first
        synchronized (lockB) {      // B second
            System.out.println("T1 done");
        }
    }
});

Thread t2Fixed = new Thread(() -> {
    synchronized (lockA) {          // A first (SAME order!)
        synchronized (lockB) {      // B second
            System.out.println("T2 done");
        }
    }
});
// No deadlock! Both threads acquire locks in A→B order.
// T1 gets A → T2 waits for A → T1 gets B → T1 finishes → T1 releases A&B
// → T2 gets A → T2 gets B → T2 finishes. SEQUENTIAL but CORRECT.

// ═══ PREVENTION STRATEGIES ═══
// 1. LOCK ORDERING: always acquire in consistent order (break circular wait)
// 2. LOCK TIMEOUT: tryLock(timeout) — give up if can't acquire in time
// 3. SINGLE LOCK: use ONE lock instead of multiple
// 4. AVOID NESTED LOCKS: redesign to not hold two locks simultaneously
// 5. DETECT: thread dump (jstack PID), ThreadMXBean.findDeadlockedThreads()

// ═══ DETECTION: jstack ═══
// jstack <PID>
// Output: "Found one Java-level deadlock:"
//   Thread-1: waiting to lock 0x00000007f...  (locked by Thread-2)
//   Thread-2: waiting to lock 0x00000007e...  (locked by Thread-1)

// ═══ DETECTION: programmatic ═══
ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
long[] deadlocked = tmx.findDeadlockedThreads();
// Returns thread IDs involved in deadlock, or null if none.
