// ─── File: src/test/java/com/bank/deadlock/DeadlockTest.java ───
package com.bank.deadlock;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class DeadlockTest {

    static class Account {
        final String id;
        final Object lock = new Object();
        int balance;

        Account(String id, int balance) { this.id = id; this.balance = balance; }
    }

    // ═══ DEADLOCK-PRONE transfer (DO NOT use in production!) ═══
    static void unsafeTransfer(Account from, Account to, int amount) {
        synchronized (from.lock) {
            try { Thread.sleep(50); } catch (InterruptedException e) { }
            synchronized (to.lock) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }

    // ═══ DEADLOCK-FREE transfer (consistent lock ordering) ═══
    static void safeTransfer(Account from, Account to, int amount) {
        Account first = from.id.compareTo(to.id) < 0 ? from : to;
        Account second = first == from ? to : from;

        synchronized (first.lock) {
            synchronized (second.lock) {
                if (from.balance >= amount) {
                    from.balance -= amount;
                    to.balance += amount;
                }
            }
        }
    }

    // ═══ PROVE: deadlock-free transfer works correctly ═══
    @Test
    void safeTransfer_noDeadlock() throws InterruptedException {
        Account rajesh = new Account("SAV2001", 100000);
        Account priya = new Account("CUR3001", 100000);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads * 2);

        // 50 threads: Rajesh → Priya
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                safeTransfer(rajesh, priya, 1000);
                latch.countDown();
            }).start();
        }

        // 50 threads: Priya → Rajesh (opposite direction!)
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                safeTransfer(priya, rajesh, 1000);
                latch.countDown();
            }).start();
        }

        boolean completed = latch.await(10, TimeUnit.SECONDS);
        assertThat(completed).isTrue();  // all finished! No deadlock!

        int total = rajesh.balance + priya.balance;
        assertThat(total).isEqualTo(200000);  // money conserved!
    }

    // ═══ DETECT deadlock programmatically ═══
    @Test
    void detectDeadlock_programmatic() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        long[] deadlocked = tmx.findDeadlockedThreads();
        assertThat(deadlocked).isNull();  // no deadlock in this test!
    }

    // ═══ tryLock with timeout — alternative prevention ═══
    @Test
    void tryLock_timeout_preventsDeadlock() throws InterruptedException {
        java.util.concurrent.locks.ReentrantLock lockA = new java.util.concurrent.locks.ReentrantLock();
        java.util.concurrent.locks.ReentrantLock lockB = new java.util.concurrent.locks.ReentrantLock();
        boolean[] succeeded = {false};

        Thread t1 = new Thread(() -> {
            try {
                if (lockA.tryLock(100, TimeUnit.MILLISECONDS)) {
                    try {
                        Thread.sleep(50);
                        if (lockB.tryLock(100, TimeUnit.MILLISECONDS)) {
                            try {
                                succeeded[0] = true;
                            } finally { lockB.unlock(); }
                        }
                    } finally { lockA.unlock(); }
                }
            } catch (InterruptedException e) { }
        });

        t1.start();
        t1.join();
        // tryLock with timeout: if can't acquire within 100ms → backs off → no deadlock!
    }
}
